//! Checks every case of `tests/data/json/corpus.txt` (generated by qjs, see
//! `tests/data/json/gen-corpus.js`). Parse cases run through all three input encodings.

use alloc::format;
use alloc::string::String;
use alloc::vec::Vec;

use super::tests::dump;
use super::*;
use crate::heap::Heap;
use crate::value::Str;

const CORPUS: &str = include_str!("../../../../tests/data/json/corpus.txt");

/// Decodes a JSON string literal (as written by JSON.stringify) into UTF-16 units.
fn lit(s: &str) -> Vec<u16> {
    let inner = s
        .strip_prefix('"')
        .and_then(|s| s.strip_suffix('"'))
        .unwrap_or_else(|| panic!("not a string literal: {s}"));
    let mut out = Vec::new();
    let mut chars = inner.chars();
    while let Some(c) = chars.next() {
        if c != '\\' {
            let mut b = [0; 2];
            out.extend_from_slice(c.encode_utf16(&mut b));
            continue;
        }
        let u = match chars.next().unwrap() {
            'b' => 8,
            'f' => 12,
            'n' => 10,
            'r' => 13,
            't' => 9,
            'u' => {
                let h: String = (0..4).map(|_| chars.next().unwrap()).collect();
                u16::from_str_radix(&h, 16).unwrap()
            }
            c => c as u16,
        };
        out.push(u);
    }
    out
}

/// A heap string with these units; `force_two_byte` makes a two-byte cell even if they
/// would fit one byte.
fn heap_str(h: &mut Heap, units: &[u16], force_two_byte: bool) -> Str {
    if !force_two_byte {
        return h.alloc_utf16(units).unwrap();
    }
    let s = h.alloc_str_uninit(units.len() as u32, true).unwrap();
    let off = Heap::str_data_offset(s);
    let dst = h.arena_mut().slice_mut(off, units.len() as u32 * 2);
    for (d, u) in dst.as_chunks_mut::<2>().0.iter_mut().zip(units) {
        *d = u.to_le_bytes();
    }
    s
}

fn outcome(h: &Heap, r: Result<crate::value::Value, ParseError>) -> String {
    match r {
        Ok(v) => format!("ok\t{}", dump(h, v)),
        Err(ParseError::Syntax(e)) => format!("err\t{}\t{}:{}", e.message, e.line, e.column),
        Err(ParseError::Heap(e)) => format!("heap\t{e:?}"),
    }
}

#[test]
fn qjs_corpus() {
    let mut parse_cases = 0;
    let mut stringify_cases = 0;
    let mut failures = Vec::new();
    for (lineno, line) in CORPUS.lines().enumerate() {
        let f: Vec<&str> = line.split('\t').collect();
        match f[0] {
            "parse" => {
                parse_cases += 1;
                let units = lit(f[1]);
                let want = f[2..].join("\t");
                let opts = ParseOptions::default();
                let mut runs = Vec::new();
                for force in [false, true] {
                    let mut h = Heap::new().unwrap();
                    let s = heap_str(&mut h, &units, force);
                    let r = parse(&mut h, s, &opts);
                    runs.push((if force { "utf16" } else { "heap" }, outcome(&h, r)));
                }
                if let Ok(text) = String::from_utf16(&units) {
                    let mut h = Heap::new().unwrap();
                    let r = parse_utf8(&mut h, text.as_bytes(), &opts);
                    runs.push(("utf8", outcome(&h, r)));
                }
                for (enc, got) in runs {
                    if got != want {
                        failures.push(format!(
                            "line {}: {enc} {}\n   want {want}\n    got {got}",
                            lineno + 1,
                            f[1]
                        ));
                    }
                }
            }
            "stringify" => {
                stringify_cases += 1;
                let mut h = Heap::new().unwrap();
                let s = heap_str(&mut h, &lit(f[1]), false);
                let v = parse(&mut h, s, &ParseOptions::default()).unwrap();
                let gap: Vec<u16> = match f[2] {
                    "-" => Vec::new(),
                    sp if sp.starts_with("n:") => gap_from_number(sp[2..].parse().unwrap()),
                    sp => gap_from_units(&lit(&sp[2..])).to_vec(),
                };
                let want = lit(f[3]);
                let got = stringify_fast(&mut h, v, &gap).unwrap().unwrap();
                let got = h.str_to_utf16(got);
                if got != want {
                    failures.push(format!(
                        "line {}: stringify {} {}\n   want {}\n    got {}",
                        lineno + 1,
                        f[1],
                        f[2],
                        String::from_utf16_lossy(&want),
                        String::from_utf16_lossy(&got)
                    ));
                }
            }
            other => panic!("line {}: unknown case kind {other}", lineno + 1),
        }
    }
    assert!(parse_cases > 1000 && stringify_cases > 300);
    assert!(
        failures.is_empty(),
        "{} failures:\n{}",
        failures.len(),
        failures[..failures.len().min(30)].join("\n")
    );
}
